//! The nested layout matrix: one layout mode inside another, against
//! Chromium.
//!
//! `tools/parity_oracle/nested_layout_matrix_cases.json` holds a few hundred
//! tiny pages, generated by `nested_layout_matrix.mjs` in the same directory:
//! an outer container (block, float, inline-block, flex row, flex column,
//! grid, absolutely positioned, table cell) holding an inner one (block, flex
//! row, flex column, grid, inline-block) at several widths and heights, then
//! riders (aspect-ratio, percentage heights through two levels, grid spans,
//! min/max clamps, an absolutely positioned child, auto margins, gap,
//! border-box, wrapping, alignment, the automatic minimum size of a flex
//! item, a flex container in a shrink-to-fit box). For every element with an
//! id the file has the border box Chromium reports; the engine must give each
//! one's x, y, width and height within 1px. No page has text and the body
//! has `font-size: 0`, so font metrics decide nothing; a baseline-aligned
//! 10x10 probe `#s` beside the inline-block outer shows its baseline without
//! a strut.
//!
//! Each page is laid out as `relayout` lays out a view (viewport set, the
//! margin-collapse entry point, the root's children as formatting roots),
//! without a view or a script, and read the way `getBoundingClientRect`
//! reads the layout (`geometry_snapshot`).
//!
//! Cases that do not match Chromium yet are listed, each with a cause tag, in
//! `nested_layout_matrix_expected_failures.txt`. Every case not listed must
//! match, and every listed case must still differ: a fix that makes one match
//! fails this test until its line is removed. The causes behind the tags are
//! in docs/layout/NESTED_LAYOUT_MATRIX_2026-10.md.
//!
//! `NESTED_MATRIX_DUMP=<file>` writes every case's engine and Chromium boxes
//! there as JSON, for working on the causes. `NESTED_MATRIX_CASES=<file>`
//! runs another case file of the same shape instead (a reduced page under
//! study) and checks nothing against the expectations file.

use super::*;
use rustkit_layout::{Dimensions, Rect};
use std::collections::HashSet;

const CASES: &str = include_str!("../../../tools/parity_oracle/nested_layout_matrix_cases.json");
const EXPECTED_FAILURES: &str =
    include_str!("../../../tools/parity_oracle/nested_layout_matrix_expected_failures.txt");
/// The cause report: every tag in the expectations file must be one of its
/// cause headings (`### N. \`tag\``), so a mistyped tag cannot quietly
/// start a new cause.
const CAUSES: &str = include_str!("../../../docs/layout/NESTED_LAYOUT_MATRIX_2026-10.md");
const TOLERANCE: f32 = 1.0;

/// `name -> cause tag` from the expectations file (`name tag`, `#` comments).
fn expected_failures() -> HashMap<String, String> {
    EXPECTED_FAILURES
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|l| {
            let mut parts = l.split_whitespace();
            let name = parts.next().unwrap().to_string();
            let tag = parts
                .next()
                .unwrap_or_else(|| panic!("no cause tag for {name}"));
            (name, tag.to_string())
        })
        .collect()
}

/// The border box of each element named in `ids`, with `document` laid out as
/// `relayout` lays a view out, as `getBoundingClientRect` would report it;
/// `None` where the element has no box.
pub(super) fn engine_rects(engine: &Engine, document: &Document, ids: &[&str]) -> Vec<Option<[f32; 4]>> {
    let mut root = engine.build_layout_from_document(document, &[]);
    root.set_viewport(1280.0, 800.0);
    let cb = Dimensions {
        content: Rect::new(0.0, 0.0, 1280.0, 0.0),
        ..Default::default()
    };
    let mut margins = rustkit_layout::MarginCollapseContext::new();
    margins.children_are_formatting_roots = true;
    root.layout_with_collapse(&cb, &mut margins, &mut rustkit_layout::FloatContext::new());
    let (geometry, _) = geometry_snapshot(&root);
    ids.iter()
        .map(|id| {
            let node = document.get_element_by_id(id)?;
            let g = geometry.get(&node.id.raw())?;
            Some([g.x, g.y, g.width, g.height])
        })
        .collect()
}

#[test]
fn nested_layout_modes_are_as_in_chromium() {
    let probe = std::env::var("NESTED_MATRIX_CASES").ok();
    let text = match &probe {
        Some(path) => std::fs::read_to_string(path).expect("NESTED_MATRIX_CASES"),
        None => CASES.to_string(),
    };
    let data: serde_json::Value = serde_json::from_str(&text).expect("case file");
    let expected = if probe.is_some() {
        HashMap::new()
    } else {
        expected_failures()
    };
    let engine = Engine::new(EngineConfig::default()).expect("engine");

    let cases = data["cases"].as_array().expect("cases");
    let names: HashSet<&str> = cases.iter().map(|c| c["name"].as_str().unwrap()).collect();
    let unknown: Vec<_> = expected
        .keys()
        .filter(|n| !names.contains(n.as_str()))
        .collect();
    assert!(
        unknown.is_empty(),
        "expected failures name no case: {unknown:?}"
    );
    let headings: Vec<&str> = CAUSES.lines().filter(|l| l.starts_with("### ")).collect();
    let mut untold: Vec<_> = expected
        .values()
        .filter(|tag| !headings.iter().any(|h| h.contains(&format!("`{tag}`"))))
        .collect();
    untold.sort();
    untold.dedup();
    assert!(
        untold.is_empty(),
        "cause tags with no heading in NESTED_LAYOUT_MATRIX_2026-10.md: {untold:?}"
    );

    // The style memo is keyed by the document's address: keep every
    // document alive so no later page can reuse an earlier one's address.
    let mut documents = Vec::new();
    let mut dump = Vec::new();
    let (mut pass, mut fail) = (0, 0);
    let mut wrong = Vec::new();
    let mut listed_but_match = Vec::new();
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let chrome: Vec<(&str, [f32; 4])> = case["rects"]
            .as_array()
            .expect("rects: run nested_layout_matrix.mjs --write")
            .iter()
            .map(|r| {
                let r = r.as_array().unwrap();
                let v = |i: usize| r[i].as_f64().unwrap() as f32;
                (r[0].as_str().unwrap(), [v(1), v(2), v(3), v(4)])
            })
            .collect();
        let ids: Vec<&str> = chrome.iter().map(|(id, _)| *id).collect();
        let document = Document::parse_html(case["html"].as_str().unwrap()).expect("parse");
        let got = engine_rects(&engine, &document, &ids);
        documents.push(document);

        let mut diffs = Vec::new();
        for ((id, c), e) in chrome.iter().zip(&got) {
            match e {
                None => diffs.push(format!("{id}: no box")),
                Some(e)
                    if e.iter()
                        .zip(c)
                        .any(|(a, b)| (a - b).abs() > TOLERANCE + 0.01) =>
                {
                    diffs.push(format!("{id}: engine {e:?} chrome {c:?}"))
                }
                _ => {}
            }
        }
        if diffs.is_empty() {
            pass += 1;
        } else {
            fail += 1;
        }
        match (diffs.is_empty(), expected.contains_key(name)) {
            (false, false) => wrong.push(format!("{name}\n    {}", diffs.join("\n    "))),
            (true, true) => listed_but_match.push(name),
            _ => {}
        }
        dump.push(serde_json::json!({
            "name": name,
            "pass": diffs.is_empty(),
            "chrome": chrome.iter().map(|(id, r)| serde_json::json!([id, r[0], r[1], r[2], r[3]])).collect::<Vec<_>>(),
            "engine": ids.iter().zip(&got).map(|(id, r)| serde_json::json!([id, r])).collect::<Vec<_>>(),
        }));
    }
    if let Ok(path) = std::env::var("NESTED_MATRIX_DUMP") {
        std::fs::write(&path, serde_json::to_string(&dump).unwrap()).expect("dump");
    }
    eprintln!(
        "nested layout matrix: {} cases, {pass} match Chromium, {fail} do not",
        cases.len()
    );
    if probe.is_some() {
        return;
    }
    assert!(
        wrong.is_empty(),
        "{} cases differ from Chromium and are not in nested_layout_matrix_expected_failures.txt:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
    assert!(
        listed_but_match.is_empty(),
        "listed as failing but match Chromium now, take them off the list: {listed_but_match:?}"
    );
}
